1: import React, { Suspense } from 'react';
2: import { Routes, Route, useLocation, Navigate } from 'react-router-dom';
3: import { AnimatePresence } from 'framer-motion';
4: import PageTransition from './components/ui/PageTransition';
5: 
6: // Route-level code splitting — each page chunk loads on demand
7: const Home = React.lazy(() => import('./pages/Home'));
8: const Dashboard = React.lazy(() => import('./pages/Dashboard'));
9: const ReportIssue = React.lazy(() => import('./pages/ReportIssue'));
10: const GitCheatSheet = React.lazy(() => import('./pages/GitCheatSheet'));
11: const AiNewsroom = React.lazy(() => import('./pages/AiNewsroom'));
12: const Company = React.lazy(() => import('./pages/Company'));
13: const TrendingLanguages = React.lazy(() => import('./pages/TrendingLanguages'));
14: const InfoPage = React.lazy(() => import('./pages/InfoPage'));
15: const NotFound = React.lazy(() => import('./pages/NotFound'));
16: 
17: /** Minimal page loader shown during route-level chunk loading */
18: const PageLoader = () => (
19:   <div
20:     role="status"
21:     aria-label="Loading"
22:     className="min-h-screen bg-[#0A0A0C] flex items-center justify-center"
23:   >
24:     <div className="four-dot-loader text-white">
25:       <span className="dot" aria-hidden="true" />
26:       <span className="dot" aria-hidden="true" />
27:       <span className="dot" aria-hidden="true" />
28:       <span className="dot" aria-hidden="true" />
29:       <span className="sr-only">Loading</span>
30:     </div>
31:   </div>
32: );
33: 
34: /** Dynamic InfoPage routes using the visual master renderer */
35: const DYNAMIC_INFO_ROUTES = ['changelog', 'docs', 'api', 'disclaimer', 'terms', 'privacy'];
36: 
37: function App() {
38:   const location = useLocation();
39: 
40:   return (
41:     <Suspense fallback={<PageLoader />}>
42:       <AnimatePresence mode="wait" initial={false}>
43:         <Routes location={location} key={location.pathname}>
44:           <Route path="/" element={<PageTransition><Home /></PageTransition>} />
45: 
46:           {/* Dashboard tabs share the same chunk */}
47:           <Route path="/dashboard" element={<PageTransition><Dashboard activeTab="explore" /></PageTransition>} />
48:           <Route path="/bookmarks" element={<PageTransition><Dashboard activeTab="bookmarks" /></PageTransition>} />
49:           <Route path="/profile" element={<PageTransition><Dashboard activeTab="profile" /></PageTransition>} />
50: 
51:           {/* Dedicated full-page routes */}
52:           <Route path="/languages" element={<PageTransition><TrendingLanguages /></PageTransition>} />
53:           <Route path="/trending-languages" element={<Navigate to="/languages" replace />} />
54:           <Route path="/report" element={<PageTransition><ReportIssue /></PageTransition>} />
55:           <Route path="/cheatsheet" element={<PageTransition><GitCheatSheet /></PageTransition>} />
56:           <Route path="/ai-news" element={<PageTransition><AiNewsroom /></PageTransition>} />
57:           <Route path="/company" element={<PageTransition><Company /></PageTransition>} />
58:           <Route path="/about" element={<Navigate to="/company" replace />} />
59:           <Route path="/features" element={<Navigate to="/docs" replace />} />
60: 
61:           {/* Dynamic content InfoPage routes with high-end vision design */}
62:           {DYNAMIC_INFO_ROUTES.map((key) => (
63:             <Route
64:               key={key}
65:               path={`/${key}`}
66:               element={<PageTransition><InfoPage contentKey={key} /></PageTransition>}
67:             />
68:           ))}
69: 
70:           <Route path="*" element={<PageTransition><NotFound /></PageTransition>} />
71:         </Routes>
72:       </AnimatePresence>
73:     </Suspense>
74:   );
75: }
76: 
77: export default App;
78: 
