1: /**
2:  * In-memory IP-based rate limiter with automated memory cleanup.
3:  * Limits each IP to MAX_REQUESTS_PER_WINDOW requests within RATE_LIMIT_WINDOW_MS.
4:  */
5: const rateLimitMap = new Map();
6: const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
7: const MAX_REQUESTS_PER_WINDOW = 120;
8: const MAX_TRACKED_IPS = 10000;
9: 
10: // Periodic cleanup to prevent memory leaks from expired IP records
11: const cleanupTimer = setInterval(() => {
12:     const now = Date.now();
13:     for (const [ip, record] of rateLimitMap.entries()) {
14:         if (now > record.resetTime) {
15:             rateLimitMap.delete(ip);
16:         }
17:     }
18: }, 5 * 60 * 1000);
19: 
20: if (cleanupTimer.unref) {
21:     cleanupTimer.unref();
22: }
23: 
24: const rateLimit = (req, res, next) => {
25:     const clientIp =
26:         req.headers['x-forwarded-for']?.split(',')[0].trim() ||
27:         req.socket.remoteAddress ||
28:         '127.0.0.1';
29: 
30:     const now = Date.now();
31:     const record = rateLimitMap.get(clientIp);
32: 
33:     if (!record) {
34:         if (rateLimitMap.size >= MAX_TRACKED_IPS) {
35:             const firstKey = rateLimitMap.keys().next().value;
36:             if (firstKey) rateLimitMap.delete(firstKey);
37:         }
38:         rateLimitMap.set(clientIp, { count: 1, resetTime: now + RATE_LIMIT_WINDOW_MS });
39:     } else if (now > record.resetTime) {
40:         record.count = 1;
41:         record.resetTime = now + RATE_LIMIT_WINDOW_MS;
42:     } else {
43:         record.count += 1;
44:         if (record.count > MAX_REQUESTS_PER_WINDOW) {
45:             return res.status(429).json({
46:                 success: false,
47:                 message: 'Too many requests. Please try again after 15 minutes.',
48:             });
49:         }
50:     }
51: 
52:     next();
53: };
54: 
55: module.exports = { rateLimit };
