            background-color: #ffffff;
        }
        .action-btn:active {
            transform: scale(0.98);
        }
    </style>
</head>
<body>
    <div class="container">
        <h1 class="error-code">${data.code}</h1>
        <h2 class="error-title">${data.title}</h2>
        <p class="error-desc">${data.description}</p>
        <div>
            <a href="${data.buttonHref}" class="action-btn">${data.buttonText}</a>
        </div>
    </div>
</body>
</html>`;
};

module.exports = { renderErrorHtml, getErrorPageData };

const logger = require('../services/logger');
const { renderErrorHtml } = require('../utils/renderErrorHtml');

/**
 * Centralized Error Handling Middleware.
 * Detects error types, returns correct HTTP status codes, logs error details,
 * and serves appropriate JSON or styled HTML error pages.
 */
const errorHandler = (err, req, res, next) => {
    let statusCode = err.statusCode || err.status || 500;
    let message = err.message || 'An unexpected error occurred.';

    // 1. Detect specific error types & map status codes
    if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
        // Malformed JSON body
        statusCode = 400;
        message = 'Malformed JSON in request payload.';
    } else if (err.name === 'ValidationError') {
        // Mongoose Schema Validation
        statusCode = 400;
        message = Object.values(err.errors || {})
            .map((e) => e.message)
            .join('; ') || 'Validation error in request payload.';
    } else if (err.name === 'CastError') {
        // Mongoose invalid ObjectId / Cast Error
        statusCode = 400;
        message = `Invalid format for resource identifier: ${err.value}`;
    } else if (err.message && err.message.includes('CORS policy')) {
        statusCode = 403;
        message = 'Forbidden: Origin is not permitted by CORS policy.';
    } else if (err.name === 'MongoServerSelectionError' || err.name === 'MongoNetworkTimeoutError') {
        statusCode = 503;
        message = 'Database service is temporarily unreachable.';
    } else if (err.code === 'ECONNREFUSED' || err.code === 'ENOTFOUND') {
        statusCode = 503;
        message = 'Upstream service is unreachable.';
    }

    // 2. Structured Error Logging
    logger.logRequestError(err, req, statusCode);

    // 3. Set standard response status
    res.status(statusCode);

    // 4. Content Negotiation: Render HTML for browser navigations or JSON for API clients
    const isApiRequest =
        req.originalUrl?.startsWith('/api/') ||
        req.originalUrl?.startsWith('/reports') ||
        req.originalUrl?.startsWith('/github') ||
        req.originalUrl?.startsWith('/models') ||
        req.xhr;

    const acceptsHtml = req.accepts('html') && !isApiRequest;

    if (acceptsHtml) {
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.send(renderErrorHtml(statusCode, statusCode >= 500 ? null : message));
    }

    // JSON response for API endpoints
    return res.json({
        success: false,
        status: statusCode,
        error: statusCode >= 500 ? 'InternalServerError' : err.name || 'Error',
        message: statusCode >= 500 && process.env.NODE_ENV === 'production'
            ? 'An unexpected error occurred. Please try again later.'
            : message,
        timestamp: new Date().toISOString()
    });
};

module.exports = { errorHandler };

const path = require('path');
const fs = require('fs');
const logger = require('../services/logger');
const { renderErrorHtml } = require('../utils/renderErrorHtml');

// Known valid SPA routes in ExploreGit
const VALID_FRONTEND_ROUTES = new Set([
    '/',
    '/dashboard',
    '/bookmarks',
    '/profile',
    '/languages',
    '/report',
    '/cheatsheet',
    '/ai-news',
    '/company',
    '/changelog',
    '/docs',
    '/api',
    '/disclaimer',
    '/terms',
    '/privacy',
    '/500',
    '/error',
    '/404'
]);

/**
 * 404 Not Found & SPA Route Handler Middleware.
 * - Serves HTTP 404 with status code and branded error page for unknown routes.
 * - Ensures search engines see HTTP 404 status header for non-existent pages.
 * - Serves valid frontend routes with HTTP 200.
 */
const notFoundHandler = (req, res, next) => {
    const rawPath = req.path.replace(/\/$/, '') || '/';
    const isApiRoute =
        req.originalUrl.startsWith('/api/') ||
        req.originalUrl.startsWith('/reports') ||
        req.originalUrl.startsWith('/github') ||
        req.originalUrl.startsWith('/models');

    const isExplicitErrorRoute = rawPath === '/500' || rawPath === '/error';

    // 1. Explicit 500 error route preview
    if (isExplicitErrorRoute && req.accepts('html')) {
        res.status(500);
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.send(renderErrorHtml(500));
    }

    // 2. Check if route is a valid frontend application route
    const isValidRoute = VALID_FRONTEND_ROUTES.has(rawPath);

    // If valid frontend route and client wants HTML, serve SPA entry point if dist exists
    if (isValidRoute && !isApiRoute && req.accepts('html')) {
        const distIndexPath = path.resolve(__dirname, '../../dist/index.html');
        if (fs.existsSync(distIndexPath)) {
            res.status(200);
            return res.sendFile(distIndexPath);
        }
    }

    // 3. If it's not a valid route or is an unmatched API route -> 404
    const err = new Error(`Cannot ${req.method} ${req.originalUrl}`);
    err.statusCode = 404;

    logger.logRequestError(err, req, 404);

    res.status(404);

    if (req.accepts('html') && !isApiRoute) {
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.send(renderErrorHtml(404, `The requested route "${req.originalUrl}" does not exist.`));
    }

    return res.json({
        success: false,
        status: 404,
        error: 'NotFoundError',
        message: `Route not found: ${req.method} ${req.originalUrl}`,
        timestamp: new Date().toISOString()
    });
};

module.exports = { notFoundHandler, VALID_FRONTEND_ROUTES };

